/**
 * Compile the vault into one file JavaScriptCore can evaluate.
 *
 * iOS ships JSC in the operating system. It evaluates a script; it does not
 * import modules, and it has no bundler of its own. So the whole of `src/`
 * plus the noble/scure cryptography becomes a single IIFE with no imports,
 * which the app loads from its resources at launch.
 *
 * Two properties this build has to preserve, both checked afterwards by
 * `test/bundle.test.ts`:
 *
 *   - it is reproducible. The same source produces the same bytes, so the
 *     committed bundle can be compared against a fresh build and a bundle that
 *     does not match its source fails the suite rather than shipping;
 *   - it contains no network. Minification renames everything, so the guard
 *     that walks `src/` cannot see inside the output; the bundle is scanned on
 *     its own terms.
 *
 * Deliberately not minified. The bundle is a build artefact that gets read by
 * anybody auditing what actually runs on the device, and saving a few hundred
 * kilobytes on a device with no network is worth less than being able to read
 * the thing you are trusting with a key.
 */

import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const OUT = 'ios/LabyrinthVault/Resources/vault.bundle.js';

mkdirSync(dirname(OUT), { recursive: true });

await build({
  entryPoints: ['src/bridge/host.ts'],
  outfile: OUT,
  bundle: true,
  format: 'iife',
  // JSC on the oldest iOS this app targets. ES2020 keeps BigInt (the amounts
  // depend on it) without assuming anything newer.
  target: ['es2020'],
  platform: 'neutral',
  minify: false,
  sourcemap: false,
  legalComments: 'inline',
  banner: {
    js: [
      '// Labyrinth Vault — generated by scripts/build-bundle.mjs. Do not edit.',
      '// Rebuild with `npm run build:bundle`; test/bundle.test.ts fails if this',
      '// file and the source it came from have drifted apart.',
    ].join('\n'),
  },
});

const bytes = readFileSync(OUT);
const digest = createHash('sha256').update(bytes).digest('hex');
writeFileSync(`${OUT}.sha256`, `${digest}\n`);

/* The same digest, as a Swift constant compiled into the binary.
 *
 * Until this existed, the bundle's integrity was checked by CI and by nothing
 * on the device. That is a real gap rather than a theoretical one: the app is
 * a Mach-O whose executable pages the operating system enforces at every fault,
 * plus half a megabyte of *data* that the app then evaluates as code. Code
 * signing does cover the resource — a modified bundle inside a signed app
 * fails the signature — but that check happens at install, and nothing on the
 * device revisits it afterwards.
 *
 * So the app revisits it. Engine.swift hashes what it loaded and compares it
 * against the constant below before a single line is evaluated. The comparison
 * is worth something precisely because the constant lives in the signed text
 * segment while the bundle does not: a swapped bundle cannot also rewrite the
 * expectation it is being measured against.
 *
 * Generated, never edited. `test/bundle.test.ts` fails if this file and the
 * bundle disagree, which is what stops a failing launch from being "fixed" by
 * pasting the new digest in.
 */
const SWIFT_OUT = 'ios/LabyrinthVault/Support/BundleDigest.swift';
mkdirSync(dirname(SWIFT_OUT), { recursive: true });
writeFileSync(
  SWIFT_OUT,
  [
    '//  BundleDigest.swift',
    '//  Generated by scripts/build-bundle.mjs. Do not edit.',
    '//',
    '//  The SHA-256 of the JavaScript this build is allowed to run. Engine.swift',
    '//  hashes the file it loaded and refuses to evaluate anything that does not',
    '//  match. Rebuild with `npm run build:bundle` rather than editing this.',
    '',
    'enum BundleDigest {',
    `    static let sha256 = "${digest}"`,
    '}',
    '',
  ].join('\n'),
);

console.log(`${OUT}  ${(bytes.length / 1024).toFixed(0)} KB  sha256 ${digest.slice(0, 16)}…`);
